values
  ('baseball', 'Baseball', true, 'baseball-mlb-v1'),
  ('basketball', 'Basketball', true, 'basketball-nba-v1')
on conflict (id) do update set
  display_name = excluded.display_name,
  is_active = excluded.is_active,
  current_content_version = excluded.current_content_version;

update storage.buckets
set allowed_mime_types = array['image/png', 'image/jpeg', 'image/svg+xml']
where id = 'quiz-assets';

