on conflict (content_version, item_id) do update set
  display_name = excluded.display_name, asset_path = excluded.asset_path, asset_sha256 = excluded.asset_sha256,
  source_page_url = excluded.source_page_url, source_asset_url = excluded.source_asset_url,
  rights_status = excluded.rights_status, attribution = excluded.attribution, difficulty = excluded.difficulty, metadata = excluded.metadata;
-- GENERATED_CONTENT_END

do $$
begin
  if (select count(*) from private.quiz_content where content_version = 'baseball-mlb-v1') <> 30 then
    raise exception 'baseball-mlb-v1 must contain all 30 current MLB teams';
  end if;
  if (select count(*) from private.quiz_content where content_version = 'basketball-nba-v1') <> 30 then
    raise exception 'basketball-nba-v1 must contain all 30 current NBA teams';
  end if;
  if exists (
    select 1 from private.quiz_content
    where content_version in ('baseball-mlb-v1', 'basketball-nba-v1')
      and jsonb_array_length(metadata->'distractorIds') <> 4
  ) then
    raise exception 'every team must have four same-division distractors';
  end if;
end;
$$;

comment on column private.quiz_content.metadata is
  'Versioned quiz metadata including scope, league, conference, division, aliases, official IDs, and reviewed distractor candidates.';

create or replace function public.get_casual_quiz_pack(p_category_id text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_content_version text;
  v_items jsonb;
begin
  perform private.require_user();
  select current_content_version into v_content_version
  from public.categories
  where id = p_category_id and is_active;
  if not found then raise exception 'Unsupported quiz.' using errcode = '22023'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', item_id,
    'displayName', display_name,
    'assetPath', asset_path,
    'difficulty', difficulty,
    'contentType', metadata->>'scope',
    'distractorIds', metadata->'distractorIds'
  ) order by item_id), '[]'::jsonb)
  into v_items
  from private.quiz_content
  where category_id = p_category_id and content_version = v_content_version;

  if jsonb_array_length(v_items) < 4 then
    raise exception 'The quiz pack is not currently playable.' using errcode = 'P0001';
  end if;
  return jsonb_build_object('categoryId', p_category_id, 'contentVersion', v_content_version, 'items', v_items);
end;
$$;

revoke all on function public.get_casual_quiz_pack(text) from public, anon;
grant execute on function public.get_casual_quiz_pack(text) to authenticated;
